{
  "analysis": "We have 380 prompt crops at 2 fps, and OCR with PSM 7 reads the prompt line reasonably (e.g., 'a', '>temp]', '>drpo_'). The crop region looks correct. Now I need OCR all prompt crops quickly and save frame-numbered command text, then parse it to reconstruct the sequence of moves.",
  "plan": "Run a loop over all prompt crops with Tesseract PSM 7, outputting frame number and OCR result to /app/prompt_ocr.txt. Use -nostdin not needed for tesseract. Then inspect the full prompt OCR list and build a move sequence by deduplicating consecutive identical commands and cleaning OCR artifacts.",
  "commands": [
    {
      "keystrokes": "i=0; for f in /app/prompts2/frame_*.png; do i=$((i+1)); printf '%04d ' \"$i\"; tesseract \"$f\" stdout --psm 7 2>/dev/null | tr '\\n' ' '; echo; done > /app/prompt_ocr.txt\n",
      "duration": 30.0
    },
    {
      "keystrokes": "wc -l /app/prompt_ocr.txt; sed -n '1,120p' /app/prompt_ocr.txt\n",
      "duration": 0.1
    }
  ]
}
